func (self class) Virtual(name string) reflect.Value {
	switch name {
	case "_get_contents_minimum_size": return reflect.ValueOf(self._get_contents_minimum_size);
	default: return gd.VirtualByName(Viewport.Advanced(self.AsViewport()), name)
	}
}

func (self Instance) Virtual(name string) reflect.Value {
	switch name {
	case "_get_contents_minimum_size": return reflect.ValueOf(self._get_contents_minimum_size);
	default: return gd.VirtualByName(Viewport.Instance(self.AsViewport()), name)
	}
}
